gaps(){return"\u062a\u064f\u0646\u0642\u0644 \u0627\u0644\u0643\u0631\u0629 \u0628\u062a\u0645\u0631\u064a\u0631\u0627\u062a \u0642\u0635\u064a\u0631\u0629. \u0648\u0644\u0627 \u062a\u0623\u062a\u064a \u0627\u0644\u0643\u0631\u0629 \u0627\u0644\u0637\u0648\u064a\u0644\u0629 \u0625\u0644\u0627 \u062d\u064a\u0646 \u062a\u0646\u0639\u062f\u0645 \u0627\u0644\u062d\u0644\u0648\u0644 \u0627\u0644\u0623\u062e\u0631\u0649."},
gapq(){return"\u062a\u064f\u0631\u0633\u0644 \u0627\u0644\u0643\u0631\u0629 \u0633\u0631\u064a\u0639\u064b\u0627 \u0625\u0644\u0649 \u0627\u0644\u0623\u0645\u0627\u0645 \u062f\u0648\u0646 \u0627\u0646\u062a\u0638\u0627\u0631 \u062a\u0645\u0631\u064a\u0631\u0629 \u0628\u064a\u0646\u064a\u0629."},
gapi(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0623\u0645\u0627\u0645 \u0645\u0646\u0637\u0642\u0629 \u062c\u0632\u0627\u0626\u0647. \u0644\u0627 \u062a\u0628\u0642\u0649 \u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647."},
gapj(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0627\u0644\u062e\u0644\u0641\u060c \u0648\u062a\u064f\u062a\u0631\u0643 \u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u0627\u0644\u062a\u064a \u0623\u0645\u0627\u0645\u0647 \u0644\u0644\u062e\u0635\u0645."},
gapk(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0641\u064a \u0646\u0635\u0641 \u0645\u0644\u0639\u0628\u0647\u060c \u0648\u0627\u0644\u0645\u0633\u0627\u0641\u0629 \u0628\u064a\u0646\u0647 \u0648\u0628\u064a\u0646 \u0627\u0644\u062d\u0627\u0631\u0633 \u0645\u063a\u0644\u0642\u0629."},
gapl(){return"\u064a\u0642\u0641 \u062e\u0637 \u0627\u0644\u062f\u0641\u0627\u0639 \u0642\u0631\u064a\u0628\u064b\u0627 \u0645\u0646 \u0648\u0633\u0637 \u0627\u0644\u0645\u0644\u0639\u0628. \u0648\u0627\u0644\u0645\u0633\u0627\u062d\u0629 \u062e\u0644\u0641\u0647 \u0648\u0627\u0633\u0639\u0629."},
